get_reddit_posts: {
  name: 'get_reddit_posts',
  description: 'Fetch top posts from a subreddit via Reddit JSON API',
  schema: { subreddit: 'string' },
  execute: async ({ subreddit }) => {
    try {
      const response = await fetch(`https://www.reddit.com/r/${subreddit}/top.json?limit=5`, { signal: AbortSignal.timeout(10000) });
      const data = await response.json();
      const posts = data.data.children.map(post => post.data.title).join('\n');
      return posts;
    } catch (error) {
      return `Error: ${error.message}`;
    }
  }
},

get_arxiv_papers: {
  name: 'get_arxiv_papers',
  description: 'Search arXiv for research papers',
  schema: { query: 'string' },
  execute: async ({ query }) => {
    try {
      const response = await fetch(`http://export.arxiv.org/api/query?search_query=${query}&max_results=3`, { signal: AbortSignal.timeout(10000) });
      const parser = new DOMParser();
      const xmlDoc = parser.parseFromString(await response.text(), 'text/xml');
      const titles = xmlDoc.getElementsByTagName('title');
      const summaries = xmlDoc.getElementsByTagName('summary');
      const papers = Array.from(titles).map((title, index) => `${title.textContent}\n${summaries[index].textContent}`).join('\n\n');
      return papers;
    } catch (error) {
      return `Error: ${error.message}`;
    }
  }
},

